  `reasons` text COLLATE utf8mb4_unicode_ci COMMENT '推荐理由JSON',
  `ai_provider` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'AI提供者',
  `model_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '使用的模型名称',
  `analysis_data` text COLLATE utf8mb4_unicode_ci COMMENT '分析用的数据JSON',
  `success` tinyint(1) DEFAULT NULL COMMENT '分析是否成功',
  `error_message` text COLLATE utf8mb4_unicode_ci COMMENT '错误信息',
  `response_time` float DEFAULT NULL COMMENT '响应时间(秒)',
  `created_at` datetime DEFAULT NULL COMMENT '创建时间',
  PRIMARY KEY (`id`),
  KEY `idx_ai_analysis_ts_code_created` (`ts_code`,`created_at`),
  KEY `idx_ai_analysis_recommendation` (`recommendation`),
  KEY `idx_ai_analysis_provider` (`ai_provider`),
  KEY `idx_ai_analysis_created_at` (`created_at`)
